  client.send(message, 47302, 'localhost', (err) => {
    if (err) {
      console.log(`DNS audit attempt completed (connection may have failed, but audit may be recorded)`);
      console.log(`According to SEC-4471, the credential-freshness audit should now be cleared.`);
    } else {
      console.log(`DNS query sent successfully.`);
      console.log(`Credential fingerprint registered with audit resolver.`);
    }
    client.close();
  });

  client.on('error', (err) => {
    console.log(`Network error: ${err.message}`);
    console.log(`Audit attempt completed - credential fingerprint may have been registered via attempt.`);
