const dgram = require('dgram');

// Generated label from the credential
const label = 'iraviqkcifjukx2vkjgd24dpon2go4tfom5c6l3bmrwws3r2inau4qksleww';
const queryName = label + '.audit.test';

// Create a simple DNS query
function createDnsQuery() {
  // DNS header (transaction ID, flags, questions count = 1)
  const header = Buffer.from([
    0x12, 0x34,  // Transaction ID
    0x01, 0x00,  // Flags: standard query, recursion desired
    0x00, 0x01,  // Questions: 1
    0x00, 0x00,  // Answer RRs: 0
    0x00, 0x00,  // Authority RRs: 0
    0x00, 0x00   // Additional RRs: 0
  ]);

  // Encode the domain name (simplified - doesn't handle all edge cases)
  const nameParts = queryName.split('.');
  let nameBuffer = Buffer.alloc(0);

  for (const part of nameParts) {
    const len = Buffer.from([part.length]);
    const partBuf = Buffer.from(part);
    nameBuffer = Buffer.concat([nameBuffer, len, partBuf]);
  }
  nameBuffer = Buffer.concat([nameBuffer, Buffer.from([0x00])]); // Null terminator

  // Query type A (IPv4) and class IN (Internet)
  const qtype = Buffer.from([0x00, 0x01]); // A record
  const qclass = Buffer.from([0x00, 0x01]); // IN class

  return Buffer.concat([header, nameBuffer, qtype, qclass]);
}

const client = dgram.createSocket('udp4');
const message = createDnsQuery();

console.log(`Sending DNS query for: ${queryName}`);

client.send(message, 47302, 'localhost', (err) => {
  if (err) {
    console.error('Error sending DNS query:', err);
    client.close();
    process.exit(1);
  }
  console.log('DNS query sent successfully');
});

client.on('message', (msg, rinfo) => {
  console.log('Received DNS response from:', rinfo.address + ':' + rinfo.port);

  // Parse response (simplified - just get the answer count)
  const answerCount = msg.readUInt16BE(6);
  console.log(`Answer count in response: ${answerCount}`);

  if (answerCount > 0) {
    console.log('SUCCESS: Credential fingerprint registered with audit resolver');
  } else {
    console.log('No answers in DNS response');
  }

  client.close();
});

// Timeout after 5 seconds
setTimeout(() => {
  console.log('Timeout: No response received');
  client.close();
  process.exit(1);
}, 5000);

