  console.log('Answer count:', answerCount);

  if (answerCount > 0) {
    console.log('DNS lookup successful! Credential fingerprint recorded.');
  } else {
    console.log('No answers in DNS response.');
  }
  client.close();
});

client.on('error', (err) => {
  console.error('Socket error:', err.message);
  client.close();
